-- Agrupa as opções em Hardware / Software / Outros e aplica os renomes pedidos por Dan (2026-11-27). Já aplicado.
update formularios set campos = (select jsonb_agg(case when e->>'chave'='falha' then e || jsonb_build_object('opcoes', $j$["BLE NOK", "BUZZER NOK", "CASE 156", "CONEXÃO FÍSICA", "DISPLAY COM FALHA", "FLASH NOK", "INPUT OUTPUT NOK", "LED COM FALHA", "MEMBRANA", "MICROCONTROLADOR QUEIMADO", "NÃO LIGA", "PLACA QUEIMADA", "REDE CAN NOK", "RFID NOK", "SERIAL PASS NOK", "SERIAL RST NOK", "BOOT NO PÓS-CHAVE", "CERCA TRAVADA", "MULTIPORTAL", "NÃO REPORTA", "SEM FALHA", "CHICOTE AVARIADO", "FALTANDO PEÇA", "RST-Mini Com Defeito", "VANDALISMO"]$j$::jsonb, 'grupos', $j$[{"titulo": "Hardware", "opcoes": ["BLE NOK", "BUZZER NOK", "CASE 156", "CONEXÃO FÍSICA", "DISPLAY COM FALHA", "FLASH NOK", "INPUT OUTPUT NOK", "LED COM FALHA", "MEMBRANA", "MICROCONTROLADOR QUEIMADO", "NÃO LIGA", "PLACA QUEIMADA", "REDE CAN NOK", "RFID NOK", "SERIAL PASS NOK", "SERIAL RST NOK"]}, {"titulo": "Software", "opcoes": ["BOOT NO PÓS-CHAVE", "CERCA TRAVADA", "MULTIPORTAL", "NÃO REPORTA"]}, {"titulo": "Outros", "opcoes": ["SEM FALHA", "CHICOTE AVARIADO", "FALTANDO PEÇA", "RST-Mini Com Defeito", "VANDALISMO"]}]$j$::jsonb) else e end order by i) from jsonb_array_elements(campos) with ordinality t(e,i)), atualizado_em = now() where slug='placas_danificadas';
